WITH all_grades AS ( SELECT grade_id, DENSE_RANK() OVER (ORDER BY CAST(score AS DECIMAL(10,2)) DESC) as full_ranking FROM competition_grade_info WHERE del_flag = '0' ) SELECT cgi.grade_id, cgi.competition_series_id, cgi.competition_stage_id, cgi.competition_track_id, cgi.second_level_code, cgi.course_id, cgi.training_program_id, cgi.member_id, cgi.user_id, cgi.score, cgi.team_code, cgi.grade_source, cgi.create_by, cgi.create_time, cgi.update_by, cgi.update_time, cgi.del_flag, cgi.version, cgi.user_name, cai.phone, cgi.id_card, cai.email, cai.leader_teacher_id, cai.competition_role_name, ag.full_ranking as ranking, csi.competition_series_name, csi.competition_name, cti.competition_track_name, ctc.second_level_name, csc.stage_name FROM competition_grade_info cgi LEFT JOIN all_grades ag ON cgi.grade_id = ag.grade_id LEFT JOIN ( SELECT a.competition_series_id, a.competition_series_name, b.competition_name FROM competition_series_info a LEFT JOIN competition_main_info b ON a.competition_id = b.competition_id ) csi ON cgi.competition_series_id = csi.competition_series_id LEFT JOIN competition_track_info cti ON cgi.competition_track_id = cti.competition_track_id LEFT JOIN competition_track_config ctc ON cgi.second_level_code = ctc.second_level_code LEFT JOIN competition_apply_info cai ON cai.member_id = cgi.member_id LEFT JOIN competition_stage_config csc on csc.stage_id = cgi.competition_stage_id WHERE cgi.del_flag = '0'
