update competition_grade_info
competition_series_id = #{competitionSeriesId}, competition_stage_id = #{competitionStageId}, competition_track_id = #{competitionTrackId}, second_level_code = #{secondLevelCode}, course_id = #{courseId}, training_program_id = #{trainingProgramId}, member_id = #{memberId}, user_id = #{userId}, score = #{score}, ranking = #{ranking}, team_code = #{teamCode}, grade_source = #{gradeSource}, user_name = #{userName}, id_card = #{idCard}, update_by = #{updateBy}, update_time = #{updateTime}, del_flag = #{delFlag}, version = version+1,
where grade_id = #{gradeId}

