select cgi.grade_id, cgi.competition_series_id, cgi.competition_stage_id, cgi.competition_track_id, cgi.second_level_code, cgi.course_id, cgi.training_program_id, cgi.member_id,
cgi.user_id, cgi.score, cgi.team_code, cgi.grade_source, cgi.create_by, cgi.create_time, cgi.update_by, cgi.update_time,
cgi.del_flag, cgi.version, cai.phone, cai.user_name, cai.id_card, cai.email,cai.leader_teacher_id,cai.competition_role_name,
DENSE_RANK() OVER (ORDER BY cgi.score DESC) as score_rank
from competition_grade_info cgi
left join competition_apply_info cai on cai.member_id = cgi.member_id
where cgi.del_flag = '0' AND cgi.id_card = #{idCard}

    and cgi.competition_series_id = #{competitionSeriesId}


    and cgi.competition_track_id = #{competitionTrackId}


    and cgi.second_level_code = #{secondLevelCode}


